#!/usr/bin/env bash
#
# This script was generated by AI, due to my complete incompetence in bash
# scripting. Feel free to report any bug in the issues.

set -euo pipefail

REPO_DIR="$(cd "$(dirname "$0")" && pwd)"
CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}"
APP="nvim-craftzdog"
STAMP="$(date +%Y%m%d-%H%M%S)"

have() {
	command -v "$1" >/dev/null 2>&1
}

at_least() {
	[ "$(printf '%s\n%s\n' "$1" "$2" | sort -V | head -n 1)" = "$1" ]
}

missing_required=""
missing_optional=""

add_required() {
	missing_required="${missing_required}  - $1"$'\n'
}
add_optional() {
	missing_optional="${missing_optional}  - $1"$'\n'
}

for cmd in git curl tar gzip unzip node npm; do
	have "$cmd" || add_required "$cmd"
done

have cc || have gcc || have clang || add_required "a C compiler (gcc or clang)"

if have nvim; then
	nvim_version="$(nvim --version | head -n 1 | sed 's/^NVIM v//')"
	at_least 0.12 "$nvim_version" || add_required "neovim >= 0.12 (found $nvim_version)"
else
	add_required "neovim >= 0.12"
fi

if have tree-sitter; then
	ts_version="$(tree-sitter --version | awk '{print $2}')"
	at_least 0.26.1 "$ts_version" || add_required "tree-sitter CLI >= 0.26.1 (found $ts_version)"
else
	add_required "tree-sitter CLI >= 0.26.1"
fi

have rg || add_optional "ripgrep (text search in the project)"
have fd || have fdfind || add_optional "fd (faster file search)"
have lazygit || add_optional "lazygit (git interface)"
have tmux || add_optional "tmux (the tmux config will be skipped)"
if ! have php || ! have composer; then
	add_optional "php + composer (PHP/Symfony support)"
fi
python3 -c 'import venv, ensurepip' >/dev/null 2>&1 || add_optional "python3 with venv (Jupyter notebooks)"

if [ -n "$missing_optional" ]; then
	echo "Optional tools not found (the config works without them):"
	printf '%s' "$missing_optional"
	echo
fi

if [ -n "$missing_required" ]; then
	echo "Missing required tools:"
	printf '%s' "$missing_required"
	echo
	echo "Install them (see README.md), then run this script again."
	echo "Nothing was changed."
	exit 1
fi

echo "All required tools are installed."

if [ "${1:-}" = "--check" ]; then
	exit 0
fi

install_config() {
	local name="$1"
	local src="$REPO_DIR/config/$name"
	local dest="$CONFIG_DIR/$name"

	if [ -d "$dest" ]; then
		if diff -rq -x plugins -x .DS_Store "$src" "$dest" >/dev/null; then
			echo "  $name: already up to date"
			return
		fi
		mv "$dest" "$dest.backup-$STAMP"
		echo "  $name: existing config saved to $dest.backup-$STAMP"
	fi

	cp -R "$src" "$dest"
	echo "  $name: installed in $dest"
}

echo
echo "Copying configs..."
mkdir -p "$CONFIG_DIR"
install_config "$APP"

if have tmux; then
	install_config tmux

	tpm_dir="$CONFIG_DIR/tmux/plugins/tpm"
	if [ ! -d "$tpm_dir" ]; then
		git clone -q --depth 1 https://github.com/tmux-plugins/tpm "$tpm_dir"
	fi

	echo "  tmux: installing plugins"
	tmux kill-session -t dotfiles-install 2>/dev/null || true
	tmux new-session -d -s dotfiles-install
	tmux source-file "$CONFIG_DIR/tmux/tmux.conf" >/dev/null 2>&1 || true
	"$tpm_dir/bin/install_plugins" >/dev/null
	tmux kill-session -t dotfiles-install
fi

alias_line="alias cvim='NVIM_APPNAME=$APP nvim'"

case "$(basename "${SHELL:-}")" in
zsh) rc_file="$HOME/.zshrc" ;;
bash) rc_file="$HOME/.bashrc" ;;
*) rc_file="" ;;
esac

echo
if [ -z "$rc_file" ]; then
	echo "Unknown shell: add this line to your shell startup file yourself:"
	echo "  $alias_line"
elif grep -qF "alias cvim=" "$rc_file" 2>/dev/null; then
	echo "Alias 'cvim' already in $rc_file"
else
	echo "$alias_line" >>"$rc_file"
	echo "Alias 'cvim' added to $rc_file"
fi

tools="twiggy-language-server pyright yaml-language-server html-lsp json-lsp css-lsp"
if have php && have composer; then
	tools="$tools phpactor php-cs-fixer"
fi
if python3 -c 'import venv, ensurepip' >/dev/null 2>&1; then
	tools="$tools jupytext"
fi

echo
echo "Downloading plugins and language servers. This takes a few minutes..."

NVIM_APPNAME="$APP" nvim --headless \
	--cmd 'lua vim.fn.confirm = function() return 1 end' \
	-c 'MasonToolsInstallSync' \
	-c "MasonInstall $tools" \
	-c 'qa!' ||
	echo "Some tools failed to install: open cvim and run :Mason to retry."

echo
echo "Done. Open a new terminal, go to a project and run: cvim ."
